    imageHint: "Mount Parker summit radar dome",
    descriptionAdvanced: {
      de: "Der Mount Parker (532 m) ist der östlichste der markanten Gipfel Hongkongs und ein Teil der „Dragon's Back“-Bergkette. Geologisch besteht er aus vulkanischem Gestein aus der Kreidezeit. Die Ostflanke fällt steil zum Cape D'Aguilar Marine Reserve ab. Der Gipfel bietet einen weiten Blick über den Südpazifik und die Inseln Po Toi und Tung Lung Chau. Im Zweiten Weltkrieg befand sich hier eine britische Radarstation. Heute ist der Mount Parker ein beliebtes Ziel für Wanderer, die den 8,5 km langen Wilson Trail begehen. Die Vegetation besteht überwiegend aus Sekundärwald mit Akazien und Bambus. In den tieferen Lagen finden sich Reste von Reisfeldterrassen aus dem 19. Jahrhundert. Die Durchschnittstemperatur auf dem Gipfel liegt im Sommer bei 28 °C, im Winter bei 15 °C. Jährlich besuchen etwa 50.000 Wanderer den Berg.",
      hu: "A Mount Parker Hongkong egyik legjellegzetesebb hegycsúcsa, 532 méteres magasságával a város keleti részén emelkedik. Nevét Sir William Parker brit admirálisról kapta, aki a 19. században jelentős szerepet játszott a térség gyarmatosításában. A hegy fontos szerepet töltött be a második világháborúban, amikor a britek radarállomást telepítettek a tetejére. A környék gazdag biodiverzitású: több mint 200 madárfajt és számos lepkefajt figyeltek meg. A hegyoldalban található a „Sárkány háta” (Dragon's Back) néven ismert turistaút, amely Hongkong egyik legkedveltebb túraútvonala. A helyi legenda szerint a hegy egy sárkány megkövesedett alakja. A közelben található Shek O falu, ahol hagyományos halászati kultúra él tovább. A Mount Parker a természetvédelem alatt álló területek része, és fontos vízgyűjtő szerepet tölt be.",
      ro: "Mount Parker (532 m) este cel mai estic dintre vârfurile proeminente ale Hong Kongului, făcând parte din lanțul „Dragon's Back”. Din punct de vedere geologic, este compus din roci vulcanice cretacice. Pe versantul estic se află rezervația marină Cape D'Aguilar. În timpul celui de-al Doilea Război Mondial, aici a funcționat o stație radar britanică. Astăzi, muntele este o destinație populară pentru drumeții, având o rețea de trasee bine marcată. Flora este dominată de păduri secundare de salcâm și bambus. În zonele joase se găsesc ruine ale teraselor de orez din secolul al XIX-lea. Temperatura medie vara este de 28 °C, iarna de 15 °C. Aproximativ 50.000 de drumeți vizitează anual muntele. De pe vârf se vede Insula Po Toi și arhipelagul Tung Lung Chau.",
      en: "Mount Parker (532 m) is the easternmost major peak of Hong Kong Island, part of the rugged Dragon's Back ridge. Its geology features Cretaceous volcanic rock, and its eastern slopes drop steeply into the Cape D'Aguilar Marine Reserve. The mountain was used by the British military as a radar station during World War II and later became a key point on the Wilson Trail, a 78 km hiking route across Hong Kong. The surrounding vegetation is secondary forest dominated by Acacia confusa and bamboo. Remains of 19th-century rice terraces are still visible on the lower slopes. Average summer temperatures reach 28 °C, while winter lows drop to 15 °C. The summit offers panoramic views of the South China Sea and the outlying islands. The area is protected as part of the Cape D'Aguilar Country Park and supports over 200 bird species.",
      es: "El Mount Parker (532 m) es el más oriental de los picos prominentes de Hong Kong y forma parte de la cordillera 'Dragon's Back'. Geológicamente, consiste en roca volcánica del período Cretácico. El flanco este cae abruptamente hacia la Reserva Marina de Cape D'Aguilar. La cima ofrece una amplia vista sobre el Pacífico Sur y las islas Po Toi y Tung Lung Chau. En la Segunda Guerra Mundial, aquí se encontraba una estación de radar británica. Hoy, Mount Parker es un destino popular para excursionistas que recorren el Wilson Trail de 8,5 km. La vegetación consiste principalmente en bosque secundario con acacias y bambú. En las elevaciones más bajas se encuentran restos de terrazas de arrozales del siglo XIX. La temperatura media en la cima es de 28 °C en verano y 15 °C en invierno. Alrededor de 50.000 excursionistas visitan la montaña anualmente.",
      pt: "O Mount Parker (532 m) é o mais oriental dos picos proeminentes de Hong Kong e faz parte da cordilheira 'Dragon's Back'. Geologicamente, consiste em rocha vulcânica do período Cretáceo. O flanco leste desce abruptamente para a Reserva Marinha de Cape D'Aguilar. O cume oferece uma vista ampla sobre o Pacífico Sul e as ilhas Po Toi e Tung Lung Chau. Na Segunda Guerra Mundial, situava-se aqui uma estação de radar britânica. Hoje, o Mount Parker é um destino popular para caminhantes que percorrem o Wilson Trail de 8,5 km. A vegetação consiste principalmente em floresta secundária com acácias e bambu. Nas zonas mais baixas, encontram-se vestígios de socalcos de campos de arroz do século XIX. A temperatura média no cume é de 28 °C no verão e 15 °C no inverno. Cerca de 50.000 caminhantes visitam a montanha anualmente.",
      fr: "Le Mount Parker (532 m) est le plus oriental des sommets marquants de Hong Kong et fait partie de la chaîne de montagnes 'Dragon's Back'. Géologiquement, il est composé de roches volcaniques du Crétacé. Le flanc est descend abruptement vers la réserve marine de Cape D'Aguilar. Le sommet offre une vue imprenable sur le Pacifique Sud et les îles Po Toi et Tung Lung Chau. Pendant la Seconde Guerre mondiale, une station radar britannique s'y trouvait. Aujourd'hui, le Mount Parker est une destination populaire pour les randonneurs qui parcourent les 8,5 km du Wilson Trail. La végétation se compose principalement de forêt secondaire avec des acacias et des bambous. Dans les zones plus basses, on trouve des restes de terrasses de rizières du XIXe siècle. La température moyenne au sommet est de 28 °C en été et de 15 °C en hiver. Environ 50 000 randonneurs visitent la montagne chaque année.",
    },
