      pt: ["Altura: 436 m", "Extração de granito no século XIX", "Parte do Wilson Trail (etapa 1) e Hong Kong Trail", "Trincheiras da Segunda Guerra Mundial (1941-1945)", "Precipitação anual: 2.200 mm", "Habitat da salamandra-gigante-chinesa"],
      fr: ["Altitude : 436 m", "Extraction de granit au XIXe siècle", "Fait partie du Wilson Trail (étape 1) et du Hong Kong Trail", "Tranchées de la Seconde Guerre mondiale (1941-1945)", "Précipitations annuelles : 2 200 mm", "Habitat de la salamandre géante de Chine"],
