      hu: "A High West egy 494 méter magas csúcs a Viktória-csúcstól nyugatra, meredek lejtőiről és kilátópontjairól ismert.",
      ro: "High West este un vârf de 494 de metri situat la vest de Vârful Victoria, cunoscut pentru versanții săi abrupți și punctele de observație.",
