    imageHint: "High West summit view toward Lamma Island",
    descriptionAdvanced: {
      de: "High West (502 m) ist der westlichste der „Drei Türme“ (nebst Mount Parker und Mount Butler) auf Hongkong Island. Der Berg besteht aus Granit und metamorphen Gesteinen der Kreidezeit. Er liegt im Lung Fu Shan Country Park. Der Name leitet sich von der englischen Bezeichnung „High West“ ab, im Gegensatz zum benachbarten „High East“ (Mount Parker). Der Gipfel ist bekannt für seine historische Bedeutung: Hier befand sich eine der letzten britischen Signalstationen aus dem 19. Jahrhundert. Die Vegetation ist tropischer Regenwald mit vielen Farnen und Orchideen. Der Berg ist ein wichtiger Rastplatz für Zugvögel wie den Graubrust-Brachschwalbe. Die durchschnittliche Luftfeuchtigkeit beträgt 80 %. Von der Spitze hat man einen weiten Blick über den Western District und die Insel Lamma. Der Berg ist durch den Lung Fu Shan Nature Trail erschlossen, einen 2,5 km langen Naturlehrpfad.",
      hu: "A High West (502 m) Hongkong-szigetének nyugati részén, a Lung Fu Shan Country Parkban található. Neve az angol „High West” kifejezésből származik, ami a magas nyugati csúcsot jelenti. A hegyet gránit és metamorf kőzetek alkotják. A 19. században itt volt a brit flotta egyik jelzőállomása, amely a hajók mozgását figyelte. A második világháború alatt a japánok elfoglalták és erődítménnyé alakították. A környék gazdag növényvilága számos ritka orchideafajt számlál. A High West fontos szerepet játszik a város vízgyűjtő rendszerében, mivel a hegyről számos patak ered. A csúcsról lenyűgöző kilátás nyílik a Nyugati kerületre, a Lamma-szigetre és a nemzetközi repülőtérre. A Lung Fu Shan Nature Trail 2,5 km hosszú, és bemutatja a helyi ökoszisztémát.",
      ro: "High West, cunoscut și sub numele de Sai Ko în dialectul local, este un vârf muntos proeminent din Hong Kong, situat la o altitudine de 494 de metri în partea de vest a Insulei Hong Kong. Poziționat strategic între faimosul Vârf Victoria și Muntele Davis, High West oferă una dintre cele mai spectaculoase panorame de 360 de grade din regiune, fără a fi la fel de aglomerat ca vecinii săi mai celebri. De pe platoul său somital, vizitatorii pot admira o perspectivă contrastantă: pe de o parte zgârie-norii impunători din districtul Central și portul Victoria, iar pe de altă parte întinderea liniștită a Rezervorului Pok Fu Lam și insulele îndepărtate din Marea Chinei de Sud. Muntele are o istorie interesantă, găzduind în trecut amplasamente de artilerie din epoca colonială, ale căror vestigii pot fi încă explorate de-a lungul traseului. Drumul către vârf este abrupt, dar bine amenajat, fiind o destinație favorită pentru fotografi în special la apus. High West rămâne un refugiu natural esențial pentru locuitorii metropolei, oferind liniște și peisaje memorabile.",
      en: "High West (502 m) is the westernmost of the Three Towers on Hong Kong Island, located in Lung Fu Shan Country Park. Its geology consists of granite and metamorphic rocks from the Cretaceous period. Historically, it housed a British naval signal station in the 19th century, used to monitor ship movements. During World War II, Japanese forces occupied and fortified the summit. The mountain is covered in tropical rainforest with abundant ferns and orchids, and serves as a stopover for migratory birds such as the Pacific golden plover. Average humidity is 80%. The Lung Fu Shan Nature Trail (2.5 km) provides educational displays about the local flora and fauna. From the peak, views extend over Western District, Lamma Island, and the Hong Kong International Airport. The mountain also supplies fresh water to the city through several streams.",
      es: "High West (502 m) es la más occidental de las 'Tres Torres' (junto a Mount Parker y Mount Butler) en la isla de Hong Kong. El monte se compone de granito y rocas metamórficas del período Cretácico. Se encuentra en el Parque Rural Lung Fu Shan. El nombre deriva de la denominación inglesa 'High West', en contraste con el vecino 'High East' (Mount Parker). La cima es conocida por su importancia histórica: aquí se encontraba una de las últimas estaciones de señales británicas del siglo XIX. La vegetación es selva tropical con muchos helechos y orquídeas. El monte es un importante lugar de descanso para aves migratorias como la canastera alinegra. La humedad media es del 80 %. Desde la cima se tiene una amplia vista sobre el Western District y la isla de Lamma. El monte es accesible a través del Lung Fu Shan Nature Trail, un sendero natural de 2,5 km.",
      pt: "High West (502 m) é o mais ocidental das 'Três Torres' (juntamente com o Mount Parker e o Mount Butler) na ilha de Hong Kong. A montanha é composta por granito e rochas metamórficas do período Cretáceo. Situa-se no Parque Rural Lung Fu Shan. O nome deriva da designação inglesa 'High West', em contraste com o vizinho 'High East' (Mount Parker). O cume é conhecido pela sua importância histórica: aqui localizava-se uma das últimas estações de sinais britânicas do século XIX. A vegetação é de floresta tropical com muitos fetos e orquídeas. A montanha é um local de paragem importante para aves migratórias, como a perdiz-do-mar-de-asa-preta. A humidade média é de 80%. Do topo, tem-se uma vista ampla sobre o Western District e a ilha de Lamma. A montanha é acessível através do Lung Fu Shan Nature Trail, um trilho de natureza com 2,5 km.",
      fr: "High West (502 m) est la plus à l'ouest des 'trois tours' (avec Mount Parker et Mount Butler) sur l'île de Hong Kong. La montagne est composée de granit et de roches métamorphiques du Crétacé. Elle se trouve dans le parc de Lung Fu Shan. Son nom provient de l'appellation anglaise 'High West', par opposition au mont Parker voisin surnommé 'High East'. Le sommet est réputé pour son importance historique : l'une des dernières stations de signalisation britanniques du XIXe siècle s'y trouvait. La végétation est une forêt tropicale humide abritant de nombreuses fougères et orchidées. La montagne est une étape importante pour les oiseaux migrateurs comme la glaréole orientale. L'humidité moyenne est de 80 %. Du sommet, on jouit d'une vue panoramique sur le district de l'Ouest et l'île de Lamma. La montagne est desservie par le Lung Fu Shan Nature Trail, un sentier éducatif de 2,5 km.",
    },
