      pt: ["A altura máxima é de 566 metros acima do nível do mar", "O nome significa 'Grande Lâmina de Espada' em cantonês", "Consiste principalmente em rocha vulcânica", "Localiza-se dentro do Parque rural de Lam Tsuen", "O cume tem apenas alguns metros de largura em alguns lugares", "Oferece vistas da fronteira com a China continental"],
      fr: ["L'altitude maximale est de 566 mètres au-dessus du niveau de la mer", "Le nom signifie « Grande lame d'épée » en cantonais", "Se compose principalement de roches volcaniques", "Se situe à l'intérieur du parc rural de Lam Tsuen", "La crête ne mesure que quelques mètres de large par endroits", "Offre une vue sur la frontière avec la Chine continentale"],
