      de: ["Höhe von 585 Metern", "Bedeutet Berg des Hahnenkamms", "Besteht überwiegend aus Grasland", "Blick auf Shenzhen und Yuen Long"],
      hu: ["585 méter magas", "Jelentése Kakasgerinc-hegy", "Főként füves pusztákból áll", "Kilátás Sencsenre és Yuen Longra"],
      ro: ["Altitudine de 585 metri", "Înseamnă Muntele Crestei de Cocoș", "Compus predominant din pajiști", "Vedere asupra Shenzhen și Yuen Long"],
