    imageHint: "Kai Kung Leng grassy slopes with Shenzhen skyline",
    descriptionAdvanced: {
      de: "Kai Kung Leng, übersetzt als der „Berg des Hahnenkamms“, ist ein markanter Bergrücken im Lam Tsuen Country Park in den nördlichen New Territories. Mit einer Höhe von 585 Metern am höchsten Punkt bietet er eine der spektakulärsten Gratwanderungen in ganz Hongkong. Im Gegensatz zu vielen anderen bewaldeten Gipfeln der Region ist Kai Kung Leng fast vollständig von Grasland bedeckt, was ihm ein offenes, hochlandartiges Erscheinungsbild verleiht. Diese fehlende Vegetation bedeutet jedoch auch, dass Wanderer der Sonne schutzlos ausgeliefert sind, was den Aufstieg besonders an heißen Tagen fordert. Von den Graten aus bietet sich ein unverstellter Panoramablick: Im Norden blickt man direkt auf die Skyline von Shenzhen und die Feuchtgebiete von Mai Po, während sich im Süden das Yuen Long-Tal erstreckt. Der Berg ist für seine steilen, oft rutschigen Pfade bekannt, die Trittsicherheit erfordern. Er ist ein beliebtes Ziel für erfahrene Wanderer und Fotografen, die die weiten Aussichten und die welligen, grünen Hügelketten schätzen, die besonders im Licht der Abendsonne eine fast magische Atmosphäre erzeugen.",
      hu: "A Kai Kung Leng, amelynek jelentése „Kakasgerinc-hegy”, az Új Területek északi részén található Lam Tsuen vidéki park egyik leglátványosabb hegyvonulata. Az 585 méter magas csúcsra vezető út Hongkong egyik legszebb gerinctúrájaként ismert. A régió sok más erdős hegyével ellentétben a Kai Kung Leng felszínét szinte teljesen fű borítja, ami különleges, felföldi jellegű megjelenést kölcsönöz neki. Ez az árnyékmentes terep azonban nagy kihívást jelent a túrázóknak, mivel a nap ellen nincs védelem a meredek emelkedőkön. A gerincről nyíló panoráma lenyűgöző: észak felé Sencsen felhőkarcolói és a Mai Po mocsárvidék látható, míg délre a Yuen Long-völgy terül el. A hegy híres meredek, néhol csúszós ösvényeiről, amelyek próbára teszik a kirándulók állóképességét. A fotósok körében is rendkívül népszerű helyszín, különösen naplemente idején, amikor az aranyló fények kiemelik a hullámzó zöld dombok vonulatait. A túra során a látogatók megtapasztalhatják Hongkong vadregényes, beépítetlen arcát, amely éles kontrasztban áll a közeli városrészek nyüzsgésével.",
      ro: "Kai Kung Leng, tradus prin „Muntele Crestei de Cocoș”, este o creastă muntoasă proeminentă situată în Parcul Rural Lam Tsuen din nordul Noilor Teritorii. Cu o altitudine maximă de 585 de metri, acest munte oferă una dintre cele mai spectaculoase experiențe de drumeție pe creastă din Hong Kong. Spre deosebire de alte vârfuri din regiune care sunt acoperite de păduri dense, Kai Kung Leng este compus aproape exclusiv din pajiști alpine și tufișuri joase, ceea ce îi conferă un aspect de platou înalt. Lipsa copacilor înseamnă că drumeții sunt expuși direct soarelui, făcând ascensiunea dificilă în zilele toride. De pe crestele sale, panorama este neîntreruptă: spre nord se poate vedea clar linia orizontului din Shenzhen și zonele umede Mai Po, în timp ce spre sud se deschide valea Yuen Long. Muntele este cunoscut pentru pantele sale abrupte și potecile uneori alunecoase, fiind recomandat celor cu experiență. Este un loc preferat pentru fotografi, în special la apus, când lumina scoate în evidență formele ondulate ale dealurilor verzi, creând un contrast vizual puternic între natura sălbatică și dezvoltarea urbană masivă de la graniță.",
      en: "Kai Kung Leng, which translates to 'Rooster Ridge Mountain,' is a prominent mountain range within the Lam Tsuen Country Park in the northern New Territories. Reaching an elevation of 585 meters, it offers one of the most exhilarating ridge-walking experiences in Hong Kong. Unlike many of the region's densely forested peaks, Kai Kung Leng is covered primarily in rolling grasslands, giving it a distinctive highland feel. This lack of shade makes the ascent particularly challenging during the humid summer months, as hikers are fully exposed to the elements. However, the reward is an unobstructed 360-degree panorama: to the north, the sprawling skyline of Shenzhen and the Mai Po marshes are clearly visible across the border, while the Yuen Long valley stretches out to the south. The mountain is famous for its steep, rugged paths that demand good stamina and sure-footedness. It is a favored destination for landscape photographers, especially during the golden hour when the light accentuates the undulating green ridges, offering a sense of vastness and tranquility that contrasts sharply with the nearby urban centers.",
      es: "Kai Kung Leng, también conocido como 'Rooster Ridge', es una prominente cresta montañosa en el Lam Tsuen Country Park, al norte de Hong Kong. Su punto más alto se encuentra a 585 metros y ofrece amplias vistas de la frontera con Shenzhen y los humedales de Mai Po. La ladera calva y cubierta de hierba es de origen volcánico y es famosa por sus exigentes y empinados senderos de senderismo.",
      pt: "Kai Kung Leng, também conhecido como 'Rooster Ridge', é uma crista montanhosa proeminente no Lam Tsuen Country Park, no norte de Hong Kong. O seu ponto mais alto situa-se a 585 metros e oferece vistas amplas sobre a fronteira com Shenzhen e as zonas húmidas de Mai Po. A encosta calva e relvada é de origem vulcânica e é conhecida pelos seus trilhos de caminhada íngremes e exigentes.",
      fr: "Le Kai Kung Leng, également connu sous le nom de « Rooster Ridge », est une crête montagneuse proeminente située dans le Lam Tsuen Country Park, au nord de Hong Kong. Son point culminant se trouve à 585 mètres et offre une vue imprenable sur la frontière avec Shenzhen et les zones humides de Mai Po. Le versant chauve et herbeux est d'origine volcanique et est réputé pour ses sentiers de randonnée escarpés et exigeants.",
    },
