      pt: ["O ponto mais alto situa-se a 585 metros", "É frequentemente referida como 'Rooster Ridge' em inglês", "Localizada no norte do Lam Tsuen Country Park", "Composta quase inteiramente por rocha vulcânica", "Oferece um panorama de 360 graus sobre Yuen Long e Shenzhen", "As encostas são quase desprovidas de árvores e cobertas de relva"],
      fr: ["Le point culminant se situe à 585 mètres", "Souvent appelée 'Rooster Ridge' en anglais", "Située dans le nord du Lam Tsuen Country Park", "Composée presque entièrement de roches volcaniques", "Offre un panorama à 360 degrés sur Yuen Long et Shenzhen", "Les pentes sont presque dépourvues d'arbres et couvertes d'herbe"],
