    imageHint: "Nei Lak Shan with Ngong Ping 360 cable car",
    descriptionAdvanced: {
      de: "Der Nei Lak Shan, mit 751 Metern der sechsthöchste Berg Hongkongs, ist ein markanter Gipfel auf der Insel Lantau. Sein Name bedeutet übersetzt 'Maitreya-Berg' und unterstreicht die spirituelle Verbindung zur nahegelegenen Ngong Ping Hochebene und dem Kloster Po Lin. Der Berg bietet einige der spektakulärsten Aussichten der Region: Von den Wanderpfaden aus blickt man direkt auf die riesige Tian Tan Buddha-Statue und die vorbeischwebenden Kabinen der Ngong Ping 360 Seilbahn. Besonders bekannt ist der Nei Lak Shan Country Trail, der den Gipfel umrundet und durch eine abwechslungsreiche Landschaft aus Grasland und dichtem Gebüsch führt. Bei klarem Wetter reicht die Sicht bis zum Flughafen Chek Lap Kok und zum Südchinesischen Meer. Die geologische Struktur des Berges besteht hauptsächlich aus Vulkangestein, was ihm seine raue und majestätische Form verleiht, die im Kontrast zu den sanften Tälern von Lantau steht.",
      hu: "A Nei Lak Shan 751 méteres magasságával Hongkong hatodik legmagasabb csúcsa, amely uralja a Lantau-sziget középső részének látképét. Neve a Maitréja Buddhára utal, ami szoros spirituális kapcsolatot jelez a szomszédos Ngong Ping-fennsíkkal és a Po Lin kolostorral. A hegy oldalában futó túraútvonalakról páratlan kilátás nyílik a monumentális Tian Tan Buddha-szoborra és a távolban húzódó Dél-kínai-tengerre. A Nei Lak Shan Country Trail népszerű a kirándulók körében, mivel viszonylag könnyen megközelíthető és lenyűgöző panorámát nyújt a Ngong Ping 360 felvonóra, valamint a Chek Lap Kok repülőtér modern termináljaira. A hegyet borító növényzet a magassággal változik, a sűrű cserjésektől a sziklás füves területekig. A csúcs elszigeteltsége és a közeli kulturális központ nyüzsgése közötti kontraszt teszi ezt a helyet a természetjárók kedvelt célpontjává.",
      ro: "Vârful Nei Lak Shan, situat pe insula Lantau, are o înălțime de 751 de metri, fiind al șaselea cel mai înalt munte din Hong Kong. Numele său se traduce prin 'Muntele lui Maitreya', reflectând legătura spirituală strânsă cu mănăstirea Po Lin și platoul Ngong Ping situat la poalele sale. Traseele de drumeție care înconjoară vârful oferă unele dintre cele mai spectaculoase perspective asupra statuii gigantice Tian Tan Buddha și a telecabinei Ngong Ping 360 care traversează peisajul montan. Vegetația de pe Nei Lak Shan este variată, incluzând pășuni alpine și arbuști rezistenți, specifice zonelor înalte expuse vântului. Într-o zi senină, de aici se pot vedea aeroportul internațional Chek Lap Kok și întinderea vastă a Mării Chinei de Sud. Este o destinație preferată pentru drumeții care caută liniște și panorame de 360 de grade asupra insulei Lantau, departe de aglomerația urbană a centrului Hong Kong-ului.",
      en: "Rising to 751 meters, Nei Lak Shan is the sixth-highest peak in Hong Kong, located centrally on Lantau Island. Its name, which means 'Maitreya Mountain,' signifies its deep spiritual proximity to the Ngong Ping plateau and the Po Lin Monastery. The mountain is renowned for its panoramic hiking trails that offer a unique perspective of the Big Buddha statue from above, as well as sweeping views of the Ngong Ping 360 cable car line. The Nei Lak Shan Country Trail provides a moderate loop that showcases the rugged volcanic terrain and high-altitude grasslands of the Lantau North Country Park. From the higher slopes, hikers can overlook the expansive Chek Lap Kok airport and the distant skyline of Macau on clear days. The peak's serene atmosphere provides a stark contrast to the busy tourist hub of Ngong Ping, making it a favored retreat for nature enthusiasts and photographers seeking dramatic mountain vistas.",
      es: "El Nei Lak Shan es, con una altura de 751 metros, el cuarto pico más alto de Hong Kong y se encuentra en la isla de Lantau. Se sitúa al norte de la meseta de Ngong Ping y ofrece amplias vistas del Buda Tian Tan, así como del aeropuerto de Chek Lap Kok. El teleférico Ngong Ping 360 recorre sus laderas, conectando Tung Chung con el monasterio Po Lin.",
      pt: "O Nei Lak Shan é, com uma altitude de 751 metros, o quarto pico mais alto de Hong Kong e situa-se na Ilha de Lantau. Localiza-se a norte do planalto de Ngong Ping e oferece amplas vistas sobre o Buda Tian Tan, bem como sobre o aeroporto Chek Lap Kok. O teleférico Ngong Ping 360 percorre as suas encostas, ligando Tung Chung ao Mosteiro Po Lin.",
      fr: "Le Nei Lak Shan est, avec une altitude de 751 mètres, le quatrième plus haut sommet de Hong Kong et se trouve sur l'île de Lantau. Il est situé au nord du plateau de Ngong Ping et offre une vue imprenable sur le Bouddha Tian Tan ainsi que sur l'aéroport de Chek Lap Kok. Le téléphérique Ngong Ping 360 longe ses pentes, reliant Tung Chung au monastère de Po Lin.",
    },
