      pt: ["Altura de 751 metros acima do nível do mar", "Quarta montanha mais alta no território de Hong Kong", "Situa-se no Parque Rural Lantau North", "Possui uma estação meteorológica no cume", "O teleférico Ngong Ping 360 passa pela montanha", "Um trilho de caminhada sobe a partir da aldeia de Ngong Ping"],
