      ro: ["Înălțime: 532 m", "Conglomerat și gresie din Terțiar", "Wilson Trail etapa 5 (9 km)", "Post de observare a incendiilor (anii 1930)", "Temperatură medie: 20 °C", "10.000 de vizitatori anual"],
