      fr: ["Altitude : 321 m", "Nommé d'après l'amiral Sir William Kellett (XIXe siècle)", "Granit et tuf volcanique", "Villas et réservoir au sommet", "Température moyenne : 23 °C", "Hong Kong Trail étape 1 (10 km)"],
