      ro: ["Înălțime: 430 m", "Numit după Sir William Nicholson (sec. XIX)", "Granit cuarțifer", "Parkview Golf Club (18 găuri)", "Precipitații anuale: 2.200 mm", "Prezența lui Rhipidura albicollis"],
