      ro: ["Înălțime: 200 m", "Numit după Jardine, Matheson & Co. (anii 1830)", "Granit și rocă alterată", "Ruine post de observație britanic WWII (1941)", "Traseul Jardine's Lookout Trail: 1,5 km", "20.000 de vizitatori anual"],
