      es: ["Altura: 200 m", "Llamado así por Jardine, Matheson & Co. (años 1830)", "Granito y roca erosionada", "Ruinas de un puesto de observación británico (1941)", "Jardine's Lookout Trail: 1,5 km", "20.000 visitantes al año"],
