      de: "Violet Hill ist ein 433 Meter hoher Berg auf Hong Kong Island, berühmt für seine seltenen Wildblumen.",
      hu: "A Violet-hegy egy 433 méter magas csúcs a Hongkong-szigeten, híres ritka vadvirágairól.",
      ro: "Violet Hill este un munte de 433 de metri pe insula Hong Kong, faimos pentru florile sale sălbatice rare.",
      en: "Violet Hill is a 433-meter mountain on Hong Kong Island, famous for its rare wildflowers.",
      es: "Violet Hill es una montaña de 433 metros de altura en la isla de Hong Kong, famosa por sus raras flores silvestres.",
