    imageHint: "Violet Hill with blooming wildflowers",
    descriptionAdvanced: {
      de: "Violet Hill (341 m) liegt auf Hongkong Island, zwischen Repulse Bay und Deep Water Bay. Der Name leitet sich von den violetten Blüten der Rhododendron-Sträucher ab, die im Frühling auf dem Hügel blühen. Geologisch besteht er aus Granit und rhyolithischem Tuff. Der Hügel ist Teil des Hong Kong Trail (Etappe 2). Er bietet einen spektakulären Blick auf die Repulse Bay und die Stanley-Halbinsel. Die Vegetation umfasst Rhododendren, Azaleen und subtropische Wälder. Auf dem Hügel befinden sich Überreste von Küstenbatterien aus dem Zweiten Weltkrieg. Die durchschnittliche jährliche Niederschlagsmenge beträgt 2.000 mm. Der Violet Hill ist ein beliebter Ort für Picknicks und Sonnenuntergangsbeobachtungen. Der Wilson Trail (Etappe 1) verläuft ebenfalls in der Nähe.",
      hu: "A Violet-hegy (Violet Hill) a Hongkong-sziget déli részén emelkedő, 433 méter magas csúcs, amely a Tai Tam Country Park területén található. Nevét nem a színéről, hanem az itt honos, ritka vadvirágokról, különösen az Enkyanthus quinqueflorus nevű harangvirágról kapta, amely a kínai újév idején rózsaszín és fehér virágba borítja a hegyoldalt. A túrázók körében a hegy rendkívül népszerű, mivel itt halad át a Wilson-ösvény (Wilson Trail) első szakasza. A csúcsról és a gerincről lenyűgöző panoráma nyílik a Repulse-öböl luxusépületeire, a Tai Tam víztározókra és a távolabbi szigetekre. A Violet-hegy megmászása gyakran az úgynevezett 'Iker-csúcsok' (The Twins) meghódításával párosul, ami bár fizikailag megterhelő a több ezer lépcsőfok miatt, a látvány kárpótolja a kirándulókat. A terület ökológiai jelentőségét a szigeten egyedülálló flóra adja, amely éles kontrasztban áll a közeli metropolisz felhőkarcolóival.",
      ro: "Violet Hill este un vârf muntos de 433 de metri situat în inima parcului natural Tai Tam de pe insula Hong Kong, fiind una dintre destinațiile preferate ale pasionaților de drumeții. Numele său provine de la prezența numeroaselor flori sălbatice care împodobesc pantele sale, în special Enkyanthus quinqueflorus, cunoscut local sub numele de 'clopoțelul chinezesc', care înflorește spectaculos în perioada Anului Nou Lunar. Traseul care traversează muntele face parte din prima secțiune a faimosului Wilson Trail și oferă unele dintre cele mai frumoase perspective panoramice din regiune. De pe culme, vizitatorii pot admira golful Repulse Bay cu plajele sale aurii, precum și rețeaua complexă de rezervoare de apă Tai Tam, înconjurate de vegetație luxuriantă. Deși ascensiunea poate fi provocatoare, în special dacă este combinată cu treptele abrupte ale vârfurilor 'The Twins', Violet Hill rămâne o oază de biodiversitate care demonstrează latura sălbatică și nealterată a Hong Kong-ului.",
      en: "Violet Hill, rising to an elevation of 433 meters, is a prominent peak within the Tai Tam Country Park on Hong Kong Island. It is widely celebrated for its ecological richness, particularly during the Lunar New Year when the rare Enkyanthus quinqueflorus, or 'Chinese New Year Flower', blooms in delicate shades of pink across its slopes. The hill is a key landmark on Section 1 of the Wilson Trail, providing hikers with a moderately challenging ascent that yields spectacular rewards. From the ridge, one can enjoy sweeping views of the opulent Repulse Bay coastline to the south and the serene Tai Tam Reservoirs to the north. Many adventurers pair a hike over Violet Hill with the daunting 'Thousand Steps' of the nearby Twins, making it a staple of Hong Kong's outdoor culture. The area serves as a vital green lung for the city, offering a stark botanical contrast to the dense urban architecture of the nearby central districts.",
      es: "Violet Hill (341 m) se encuentra en la isla de Hong Kong, entre Repulse Bay y Deep Water Bay. El nombre deriva de las flores violetas de los arbustos de rododendro que florecen en la colina en primavera. Geológicamente, consiste en granito y toba riolítica. La colina forma parte del Hong Kong Trail (etapa 2). Ofrece una vista espectacular de Repulse Bay y la península de Stanley. La vegetación incluye rododendros, azaleas y bosques subtropicales. En la colina se encuentran restos de baterías costeras de la Segunda Guerra Mundial. La precipitación media anual es de 2.000 mm. Violet Hill es un lugar popular para picnics y observación de puestas de sol. El Wilson Trail (etapa 1) también pasa cerca.",
      pt: "Violet Hill (341 m) localiza-se na ilha de Hong Kong, entre Repulse Bay e Deep Water Bay. O nome deriva das flores violetas dos arbustos de rododendro que florescem na colina na primavera. Geologicamente, consiste em granito e tufo riolítico. A colina faz parte do Hong Kong Trail (etapa 2). Oferece uma vista espetacular da Repulse Bay e da península de Stanley. A vegetação inclui rododendros, azáleas e florestas subtropicais. Na colina encontram-se vestígios de baterias costeiras da Segunda Guerra Mundial. A precipitação média anual é de 2.000 mm. Violet Hill é um local popular para piqueniques e observação do pôr do sol. O Wilson Trail (etapa 1) também passa por perto.",
      fr: "Violet Hill (341 m) est situé sur l'île de Hong Kong, entre Repulse Bay et Deep Water Bay. Son nom provient des fleurs violettes des buissons de rhododendrons qui fleurissent sur la colline au printemps. Géologiquement, il est composé de granit et de tuf rhyolitique. La colline fait partie du Hong Kong Trail (étape 2). Elle offre une vue spectaculaire sur Repulse Bay et la péninsule de Stanley. La végétation comprend des rhododendrons, des azalées et des forêts subtropicales. Sur la colline se trouvent les vestiges de batteries côtières de la Seconde Guerre mondiale. Les précipitations annuelles moyennes sont de 2 000 mm. Violet Hill est un lieu prisé pour les pique-niques et l'observation des couchers de soleil. Le Wilson Trail (étape 1) passe également à proximité.",
    },
