    imageHint: "Devil's Peak military ruins at sunset",
    descriptionAdvanced: {
      de: "Devil's Peak (402 m) liegt in den New Territories, östlich von Kowloon. Der Name stammt von der steilen, teuflisch schwierigen Kletterei. Geologisch besteht er aus Granit und metamorphen Gesteinen. Der Berg ist Teil des Ma On Shan Country Park. Er bietet einen weiten Blick über den Tolo Harbour und die Inseln im Mirs Bay. Während der japanischen Besatzung (1941-1945) wurde der Berg als Aussichtspunkt genutzt. Die Vegetation besteht aus Buschland, Gras und vereinzelten Kiefern. Auf dem Berg leben Wildschweine, Zibetkatzen und der Chinesische Feuersalamander. Die durchschnittliche jährliche Temperatur beträgt 22 °C. Der Devil's Peak ist bekannt für seine anspruchsvollen Wanderwege mit steilen Abschnitten. Auf dem Gipfel befindet sich ein alter trigonometrischer Punkt.",
      hu: "Az Ördög-csúcs (Devil's Peak) egy stratégiai fontosságú magaslat Hongkong keleti részén, amely 222 méter magasan magasodik a Lei Yue Mun-csatorna fölé. A hegy neve a helyi történelem sötétebb korszakaiból ered, amikor kalózok használták búvóhelyül és megfigyelőpontként, hogy ellenőrizzék a kikötőbe érkező hajókat. Később, a brit gyarmati uralom idején a területet fontos védelmi vonallá alakították; a csúcson és az oldalakon ma is láthatók az egykori Gough-üteg és Pottinger-üteg romjai, amelyek a tüzérségi állásokat és a lőszerraktárakat foglalták magukba. A hegy ma a Wilson Trail 3. szakaszának népszerű megállója, ahonnan lélegzetelállító kilátás nyílik a Victoria-öbölre, a Junk-öbölre és a Kowloon-félsziget felhőkarcolóira. A látogatók számára a hely a történelmi romok felfedezésének és a modern városi panoráma élvezetének különleges ötvözetét kínálja, ahol a természet és a hadi építészet nyomai találkoznak.",
      ro: "Devil's Peak, situat în estul peninsulei Kowloon, este un punct de reper istoric și geografic ce domină intrarea estică în portul Victoria, deasupra canalului Lei Yue Mun. Cu o înălțime de 222 de metri, acest munte a jucat un rol crucial în apărarea Hong Kong-ului timp de secole. Numele său provine din perioada în care zona era un refugiu pentru pirați, care profitau de vizibilitatea excelentă pentru a ataca navele comerciale. Ulterior, sub administrație britanică, muntele a fost fortificat cu baterii de coastă precum Gough și Pottinger, ale căror ruine fascinante pot fi explorate și astăzi de către turiști. Traseul către vârf face parte din secțiunea 3 a faimosului Wilson Trail, oferind drumeților o perspectivă unică asupra contrastului dintre rămășițele militare din beton și peisajul urban ultra-modern al orașului. Panorama de pe vârf, care cuprinde atât marea, cât și zgârie-norii din cartierele învecinate, face din Devil's Peak una dintre cele mai căutate destinații pentru pasionații de fotografie și istorie locală.",
      en: "Devil's Peak stands as a prominent 222-meter sentinel overlooking the Lei Yue Mun channel, the eastern gateway to Victoria Harbour in Hong Kong. Its evocative name dates back to the Ming and early Qing dynasties when the area was a notorious stronghold for pirates who preyed on merchant vessels navigating the narrow waters. Recognizing its strategic value, the British military later transformed the peak into a key defensive position, constructing the Gough Battery and Pottinger Battery during the early 20th century. Today, the skeletal remains of these concrete fortifications, including gun emplacements and observation posts, offer a haunting glimpse into the city's wartime past. The peak is a highlight of Section 3 of the Wilson Trail, attracting hikers not only for its historical significance but also for the unparalleled panoramic views it affords. From the summit, one can see the dense skyline of Kowloon, the expanse of Junk Bay, and the rugged coastline of Hong Kong Island, making it a perfect spot to witness the intersection of nature, history, and urban expansion.",
      es: "Devil's Peak (402 m) se encuentra en los Nuevos Territorios, al este de Kowloon. El nombre procede de la escalada diabólicamente difícil. Geológicamente, se compone de granito y rocas metamórficas. El monte forma parte del Parque Rural Ma On Shan. Ofrece una amplia vista sobre el puerto de Tolo y las islas de la bahía de Mirs. Durante la ocupación japonesa (1941-1945), el monte se utilizó como puesto de observación. La vegetación consiste en matorrales, hierba y pinos dispersos. En el monte viven jabalíes, civetas y el salamandra de fuego china. La temperatura media anual es de 22 °C. Devil's Peak es conocido por sus desafiantes rutas de senderismo con tramos empinados. En la cima se encuentra un antiguo punto trigonométrico.",
      pt: "Devil's Peak (402 m) situa-se nos Novos Territórios, a leste de Kowloon. O nome provém da escalada diabolicamente difícil. Geologicamente, é composta por granito e rochas metamórficas. A montanha faz parte do Parque Rural Ma On Shan. Oferece uma vista ampla sobre o Porto de Tolo e as ilhas na baía de Mirs. Durante a ocupação japonesa (1941-1945), a montanha foi utilizada como posto de observação. A vegetação consiste em matagal, erva e pinheiros isolados. Na montanha vivem javalis, civetas e a salamandra-de-fogo-chinesa. A temperatura média anual é de 22 °C. Devil's Peak é conhecido pelos seus trilhos de caminhada desafiantes com secções íngremes. No cume encontra-se um antigo ponto trigonométrico.",
      fr: "Devil's Peak (402 m) est situé dans les Nouveaux Territoires, à l'est de Kowloon. Son nom vient de l'escalade d'une difficulté diabolique. Géologiquement, il est composé de granit et de roches métamorphiques. Le mont fait partie du parc de Ma On Shan. Il offre une vue panoramique sur le port de Tolo et les îles de la baie de Mirs. Pendant l'occupation japonaise (1941-1945), la montagne servait de poste d'observation. La végétation se compose de broussailles, d'herbe et de pins clairsemés. Des sangliers, des civettes et la salamandre de feu de Chine vivent sur la montagne. La température annuelle moyenne est de 22 °C. Devil's Peak est réputé pour ses sentiers de randonnée exigeants avec des sections escarpées. Un ancien point trigonométrique se trouve au sommet.",
    },
    factsAdvanced: {
      de: ["Höhe: 402 m", "Name bezieht sich auf die schwierige Kletterei", "Granit und metamorphes Gestein", "Japanischer Aussichtsposten (1941-1945)", "Durchschnittstemperatur: 22 °C", "Alter trigonometrischer Punkt"],
      hu: ["Magasság: 402 méter", "Név: ördögien nehéz mászás", "Gránit és metamorf kőzet", "Japán megfigyelőpont (1941-1945)", "Átlagos hőmérséklet: 22 °C", "Régi trigonometriai pont"],
      ro: ["Înălțime: 402 m", "Numele se referă la ascensiunea dificilă", "Granit și roci metamorfice", "Post de observație japonez (1941-1945)", "Temperatură medie anuală: 22 °C", "Vechi punct trigonometric"],
      en: ["Elevation: 402 m (1,319 ft)", "Named for challenging climb", "Granite and metamorphic rock", "Japanese lookout post during WWII (1941-1945)", "Average annual temperature: 22 °C (71.6 °F)", "Historical trigonometrical station"],
      es: ["Altura: 402 m", "El nombre se refiere a la difícil escalada", "Granito y roca metamórfica", "Puesto de observación japonés (1941-1945)", "Temperatura media: 22 °C", "Antiguo punto trigonométrico"],
      pt: ["Altura: 402 m", "O nome refere-se à escalada difícil", "Granito e rocha metamórfica", "Posto de observação japonês (1941-1945)", "Temperatura média: 22 °C", "Antigo ponto trigonométrico"],
      fr: ["Hauteur : 402 m", "Le nom fait référence à l'escalade difficile", "Granit et roche métamorphique", "Poste d'observation japonais (1941-1945)", "Température moyenne : 22 °C", "Ancien point trigonométrique"],
    },
