      pt: ["High Junk Peak tem 344 metros de altura.", "A montanha situa-se no Parque Rural Clear Water Bay.", "O cume oferece uma vista sobre 9 ilhas no Port Shelter.", "As rochas datam do período Jurássico, com cerca de 140 milhões de anos.", "O High Junk Peak Trail tem cerca de 6,5 quilómetros de comprimento.", "A montanha faz parte do distrito de Sai Kung."],
