      pt: "West Buffalo Hill é um cume de 604 metros de altura que forma um maciço de cume duplo juntamente com o Buffalo Hill.",
      fr: "West Buffalo Hill est un sommet de 604 mètres de haut qui forme un massif à double sommet avec Buffalo Hill.",
