      pt: ["Mount Austin tem 463 metros de altura.", "A montanha situa-se no Lung Fu Shan Country Park.", "O antigo posto de observação data da Segunda Guerra Mundial.", "O Mount Austin Trail tem 2,8 quilómetros de comprimento.", "A montanha oferece uma vista direta para o Victoria Peak (552 m).", "A área envolvente tem uma humidade média do ar de 80%."],
      fr: ["Le Mount Austin mesure 463 mètres de haut.", "La montagne est située dans le Lung Fu Shan Country Park.", "L'ancien poste d'observation date de la Seconde Guerre mondiale.", "Le sentier du Mount Austin fait 2,8 kilomètres de long.", "La montagne offre une vue directe sur le Victoria Peak (552 m).", "L'environnement affiche une humidité moyenne de 80 %."],
