      es: ["Pottinger Peak tiene 406 metros de altura.", "La montaña se encuentra en el parque rural de Aberdeen.", "El sendero Pottinger Peak Trail tiene 2,5 kilómetros de longitud.", "La cima se utiliza frecuentemente para el parapente.", "La temperatura promedio es de 22 grados Celsius.", "La montaña ofrece una vista de la playa de Deep Water Bay."],
