    imageHint: "Mount Collinson view toward Chai Wan",
    descriptionAdvanced: {
      de: "Der Mount Collinson erhebt sich mit einer Höhe von 348 Metern im östlichen Teil von Hong Kong Island und stellt eine markante Erhebung über dem Stadtteil Chai Wan dar. Der Berg ist nach dem britischen Vermessungsingenieur Thomas Bernard Collinson benannt, der Mitte des 19. Jahrhunderts maßgeblich an der kartografischen Erfassung Hongkongs beteiligt war. Die Hänge des Berges sind heute vor allem für den Cape Collinson Friedhof bekannt, dessen terrassenförmig angelegte Grabstätten sich imposant an die steilen Flanken schmiegen und ein friedliches Bild über dem urbanen Trubel vermitteln. Wanderer schätzen den Mount Collinson für seine gut begehbaren Pfade, die Verbindungen zum Pottinger Peak und zum berühmten Dragon's Back Trail bieten. Vom Gipfel aus eröffnet sich ein weiter Blick über den Tathong-Kanal, die Halbinsel Clearwater Bay und die geschäftigen Schifffahrtswege, die zum Hafen führen. Die Vegetation besteht aus dichtem subtropischem Buschwerk, das einen natürlichen Kontrast zu den Hochhausschluchten des nahegelegenen Chai Wan bildet.",
      hu: "A Mount Collinson egy 348 méter magas hegycsúcs Hongkong-sziget keleti részén, amely Chai Wan sűrűn lakott negyede felett magasodik. A hegy nevét Thomas Bernard Collinson brit hadmérnökről kapta, aki az 1840-es években elkészítette Hongkong első részletes térképét. A hegyoldalak egyik legjellegzetesebb látványa a Cape Collinson temető, amelynek teraszos kialakítású sírhelyei lépcsőzetesen követik a terep adottságait, különleges vizuális élményt nyújtva a tenger felől nézve. A túrázók körében kedvelt célpont, hiszen ösvényei összeköttetést biztosítanak a Pottinger-csúccsal és a népszerű Dragon's Back útvonallal. A csúcsról pazar kilátás nyílik a Tathong-csatornára, ahol a nemzetközi teherhajók sorakoznak a kikötőbe menet, valamint a szemközti Clearwater Bay-félszigetre. A hegy dús, szubtrópusi növényzete és a sziklák nyers formái éles kontrasztban állnak a közeli lakótelepek betontömbjeivel, menedéket nyújtva a városi zaj elől.",
      ro: "Mount Collinson este un vârf muntos cu o altitudine de 348 de metri situat în partea de est a insulei Hong Kong, dominând peisajul deasupra districtului Chai Wan. Muntele poartă numele căpitanului Thomas Bernard Collinson, un inginer militar britanic care a realizat prima hartă topografică detaliată a regiunii în secolul al XIX-lea. Versanții săi sunt astăzi recunoscuți în principal pentru cimitirul Cape Collinson, ale cărui morminte dispuse în terase pe pantele abrupte creează o imagine arhitecturală unică deasupra mării. Pentru entuziaștii de drumeții, Mount Collinson oferă trasee accesibile care fac legătura cu Pottinger Peak și celebra potecă Dragon's Back. De pe culme, vizitatorii pot admira o panoramă vastă asupra canalului Tathong, unde pot fi observate navele mari care intră în port, precum și Peninsula Clearwater Bay în depărtare. Vegetația subtropicală densă de pe munte oferă un contrast natural puternic față de zgârie-norii din Chai Wan, fiind o destinație populară pentru cei care caută liniște și aer curat în apropierea orașului.",
      en: "Mount Collinson rises to an elevation of 348 meters on the eastern end of Hong Kong Island, serving as a prominent backdrop to the high-rise district of Chai Wan. The mountain is named after Captain Thomas Bernard Collinson, a British Royal Engineer who carried out the first comprehensive survey of Hong Kong's terrain in the 1840s. Its slopes are notably home to the Cape Collinson Cemetery, where terraced burial plots are intricately carved into the steep hillsides, creating a striking visual pattern visible from the sea. Hikers frequent the area for its scenic trails, which link up with Pottinger Peak and the world-renowned Dragon's Back coastal path. From the summit, one can enjoy expansive views of the Tathong Channel, the Clearwater Bay Peninsula, and the constant stream of maritime traffic entering Victoria Harbour. The mountain’s lush subtropical greenery and rugged rock formations provide a refreshing natural escape from the urban density below, blending spiritual significance with outdoor recreation.",
      es: "Mount Collinson (351 m) se ubica en el Shek O Country Park, isla de Hong Kong. Nombrado por el oficial británico Sir Thomas Collinson, ofrece vistas impresionantes del Mar de China Meridional y las islas de Shek O. El sendero es corto pero empinado, rodeado de vegetación costera y arboledas de protección contra el viento. Es un lugar predilecto para la fotografía de amaneceres debido a su proximidad al océano.",
      pt: "O Mount Collinson é uma montanha de 351 metros na ilha de Hong Kong, no Shek O Country Park. O seu nome deve-se ao oficial britânico Sir Thomas Collinson. A montanha oferece vistas deslumbrantes sobre o Mar da China Meridional e as ilhas de Shek O. O Mount Collinson Trail é um trilho curto mas íngreme. A vegetação consiste em bosques de proteção e vegetação costeira, sendo um local popular para fotografia ao nascer do sol.",
      fr: "Le Mount Collinson est une montagne de 351 mètres sur l'île de Hong Kong, située dans le Shek O Country Park. Il doit son nom à l'officier britannique Sir Thomas Collinson. La montagne offre une vue imprenable sur la mer de Chine méridionale et les îles de Shek O. Le sentier du Mount Collinson est un chemin court mais escarpé. La végétation se compose de bois protecteurs et d'une flore côtière, en faisant un lieu prisé pour la photographie au lever du soleil.",
    },
    factsAdvanced: {
      de: ["Mount Collinson ist 351 Meter hoch.", "Der Berg liegt im Shek O Country Park.", "Der Trail ist 1,8 Kilometer lang.", "Der Berg bietet einen Blick auf 5 Inseln.", "Die Steigung beträgt bis zu 30 Grad.", "Der Gipfel ist nur 150 Meter vom Meer entfernt."],
      hu: ["A Mount Collinson magassága 351 méter.", "A hegy a Shek O Country Parkban található.", "Az ösvény 1,8 kilométer hosszú.", "A hegy 5 szigetre nyújt kilátást.", "A meredekség elérheti a 30 fokot.", "A csúcs mindössze 150 méterre van a tengertől."],
      ro: ["Mount Collinson are o înălțime de 351 de metri.", "Muntele se află în Parcul Rural Shek O.", "Traseul are 1,8 kilometri.", "Muntele oferă vedere către 5 insule.", "Panta atinge până la 30 de grade.", "Vârful este la doar 150 de metri de mare."],
      en: ["Mount Collinson is 351 meters high.", "It is located in Shek O Country Park.", "The trail is 1.8 kilometers long.", "The mountain offers views of 5 islands.", "The gradient reaches up to 30 degrees.", "The summit is only 150 meters from the sea."],
      es: ["Mount Collinson tiene 351 metros de altura.", "La montaña se encuentra en el Shek O Country Park.", "El sendero tiene 1,8 kilómetros de longitud.", "Desde la montaña se ven 5 islas.", "La pendiente alcanza hasta los 30 grados.", "La cima se encuentra a solo 150 metros del mar."],
      pt: ["O Mount Collinson tem 351 metros de altura.", "A montanha situa-se no Shek O Country Park.", "O trilho tem 1,8 quilómetros de comprimento.", "A montanha oferece vista para 5 ilhas.", "A inclinação chega aos 30 graus.", "O cume fica a apenas 150 metros do mar."],
      fr: ["Le Mount Collinson mesure 351 mètres de haut.", "La montagne est située dans le Shek O Country Park.", "Le sentier fait 1,8 kilomètre de long.", "La montagne offre une vue sur 5 îles.", "La pente atteint jusqu'à 30 degrés.", "Le sommet n'est qu'à 150 mètres de la mer."],
    },
